dashboard.definition:
{
  "title": "PulseForge · Routing-loop indicators (flow-only)",
  "description": "Are the same source/destination pairs being observed repeatedly at several exporters and interfaces, in the pattern a forwarding loop would produce?",
  "inputs": {
    "input_global_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_run": {
      "type": "input.dropdown",
      "title": "Scenario run",
      "options": {
        "token": "run_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All runs",
            "value": "*"
          }
        ],
        "createSearchJobOnChange": false,
        "clearDefaultOnSelection": false
      },
      "dataSources": {
        "primary": "ds_runs"
      },
      "context": {}
    },
    "input_index": {
      "type": "input.text",
      "title": "Index",
      "options": {
        "token": "index_tok",
        "defaultValue": "dev_test_replay"
      }
    },
    "input_st": {
      "type": "input.text",
      "title": "Sourcetype",
      "options": {
        "token": "st_tok",
        "defaultValue": "netflow:collector"
      }
    },
    "input_minobs": {
      "type": "input.text",
      "title": "Min observations per pair",
      "options": {
        "token": "minobs",
        "defaultValue": "10"
      }
    },
    "input_maxpkts": {
      "type": "input.text",
      "title": "Max avg packets per flow",
      "options": {
        "token": "maxpkts",
        "defaultValue": "3"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### **PulseForge** · NetFlow/IPFIX · NOC-03\n**Routing-loop indicators (flow-only)**  ·  `NF-NOC-03-ROUTING-LOOP`\n\n**Question:** Are the same source/destination pairs being observed repeatedly at several exporters and interfaces, in the pattern a forwarding loop would produce?\n\n**Limits:** INDICATOR ONLY. NetFlow has no TTL, so TTL depletion and loop drops are not shown. Confirmation needs ICMP time-exceeded messages or router counters, which are not in this data.",
        "fontColor": "#ececea",
        "backgroundColor": "#17191b",
        "fontSize": "default"
      }
    },
    "viz_2": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "#### How to read this\nA pair is flagged when it is seen at **two or more exporters**, at least **N times**, with **small flows** (few packets each). That pattern is *consistent with* repeated traversal of a path, and also with asymmetric paths, load balancing or sampling. Treat the table as a worklist, not a verdict.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a",
        "fontSize": "default"
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#c9786f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 0
      },
      "title": "Flagged pairs",
      "dataSources": {
        "primary": "ds_1"
      },
      "showProgressBar": true
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#d4764f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 0
      },
      "title": "Indicator flows",
      "dataSources": {
        "primary": "ds_2"
      },
      "showProgressBar": true
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#d4764f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 0
      },
      "title": "Exporters involved",
      "dataSources": {
        "primary": "ds_3"
      },
      "showProgressBar": true
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#22262a",
        "majorColor": "#d4764f",
        "majorFontSize": 40,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "numberPrecision": 1,
        "unit": "%"
      },
      "title": "Share of all flows",
      "dataSources": {
        "primary": "ds_4"
      },
      "showProgressBar": true
    },
    "viz_7": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#22262a",
        "count": 6
      },
      "title": "Flagged source/destination pairs (click a row for the supporting flows)",
      "dataSources": {
        "primary": "ds_5"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" src=\"$row.src.value$\" dest=\"$row.dest.value$\" | sort 0 _time | head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_8": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#22262a",
        "seriesColors": [
          "#9aa1a6",
          "#c9786f"
        ],
        "legendDisplay": "bottom",
        "yAxisTitleText": "flow records"
      },
      "title": "Anomaly trend: indicator flows vs all flows",
      "dataSources": {
        "primary": "ds_6"
      },
      "showProgressBar": true
    },
    "viz_9": {
      "type": "splunk.bar",
      "options": {
        "backgroundColor": "#22262a",
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "off"
      },
      "title": "Affected exporter / interface path (indicator flows)",
      "dataSources": {
        "primary": "ds_7"
      },
      "showProgressBar": true
    },
    "viz_10": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#22262a",
        "count": 6
      },
      "title": "Supporting flow evidence (flagged pairs)",
      "dataSources": {
        "primary": "ds_8"
      },
      "showProgressBar": true
    },
    "viz_11": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "**Data prerequisites.** Events: index `$index_tok$`, sourcetype `$st_tok$`, source `netspout:netflow:normalized`, scenario `NF-NOC-03-ROUTING-LOOP`, filtered by run (`netspout_run_id`). Flows are synthetic (RFC 5737 documentation addresses); `label_meta` is scenario truth, not exporter data. Fields used: src, dest, dest_port, exporter_ip, snmp_in, snmp_out, packets. **If every panel is empty:** no run of this scenario is indexed in the selected time range and index. Start it from the PulseForge Use Case Explorer (Run scenario with live delivery monitor) and wait for Dashboard READY. CIM names (`src`, `dest`, `transport`) come from the app's props.conf; no accelerated data model is assumed.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a",
        "fontSize": "default"
      }
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Flagged pairs",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | where indicator=1 | stats dc(src) as v by dest | stats sum(v) as v | fields v"
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Indicator flows",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | stats sum(indicator) as v | fields v"
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Exporters involved",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | where indicator=1 | stats dc(exporter_ip) as v | fields v"
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Share of all flows",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | stats sum(indicator) as i count as n | eval v=round(100*i/n,1) | fields v"
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Flagged source/destination pairs (click a row for the supporting flows)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | where indicator=1 | stats count as observations dc(exporter_ip) as exporters values(exporter_ip) as exporter_list values(snmp_in) as ingress_if values(snmp_out) as egress_if avg(packets) as avg_pkts min(_time) as first_seen max(_time) as last_seen by src dest dest_port | eval avg_pkts=round(avg_pkts,1), first_seen=strftime(first_seen,\"%H:%M:%S\"), last_seen=strftime(last_seen,\"%H:%M:%S\") | sort - observations"
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Anomaly trend: indicator flows vs all flows",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | bin _time span=15s | stats count as all_flows sum(indicator) as indicator_flows by _time | makecontinuous _time span=15s | fillnull value=0"
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Affected exporter / interface path (indicator flows)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | where indicator=1 | eval path=exporter_ip.\"  if\".snmp_in.\"→\".snmp_out | stats count by path | sort - count"
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Supporting flow evidence (flagged pairs)",
      "options": {
        "query": "index=$index_tok$ sourcetype=$st_tok$ source=\"netspout:netflow:normalized\" netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" netspout_run_id=\"$run_tok$\" | eventstats count as obs dc(exporter_ip) as exporters avg(packets) as avg_pkts by src dest dest_port | eval indicator=if(obs>=$minobs$ AND exporters>=2 AND avg_pkts<=$maxpkts$,1,0) | where indicator=1 | sort - _time | head 200 | eval start=strftime(flowStartMilliseconds/1000,\"%H:%M:%S\") | foreach app tcp_flags_text [eval <<FIELD>>=if(isnull(<<FIELD>>) OR <<FIELD>>=\"null\",\"-\",<<FIELD>>)] | table start exporter_ip src src_port dest dest_port transport app tcp_flags_text dscp packets bytes duration_ms snmp_in snmp_out label_meta.is_malicious"
      }
    },
    "ds_runs": {
      "type": "ds.search",
      "name": "Run list",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"NF-NOC-03-ROUTING-LOOP\" | stats latest(_time) as t count by netspout_run_id | sort - t | eval label=netspout_run_id.\" · \".strftime(t,\"%m-%d %H:%M\").\" · \".count.\" flows\" | table label netspout_run_id"
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_time",
      "input_run",
      "input_index",
      "input_st",
      "input_minobs",
      "input_maxpkts"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "type": "absolute",
        "options": {
          "width": 1460,
          "height": 1310,
          "display": "auto-scale",
          "backgroundColor": "#17191b"
        },
        "structure": [
          {
            "item": "viz_1",
            "type": "block",
            "position": {
              "x": 20,
              "y": 0,
              "w": 1420,
              "h": 124
            }
          },
          {
            "item": "viz_2",
            "type": "block",
            "position": {
              "x": 20,
              "y": 134,
              "w": 460,
              "h": 190
            }
          },
          {
            "item": "viz_3",
            "type": "block",
            "position": {
              "x": 500,
              "y": 134,
              "w": 220,
              "h": 190
            }
          },
          {
