            }
          }
        ]
      }
    },
    "tabs": {
      "items": [
        {
          "label": "Routing-loop indicators (flow-only)",
          "layoutId": "layout_1"
        }
      ]
    }
  },
  "expressions": {},
  "applicationProperties": {
    "hideEdit": false,
    "hideExport": false
  }
}
